// Content with portions generated by generative AI platform
package org.eclipse.kura.rest.configuration.provider.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Collections;
import java.util.Dictionary;
import java.util.Hashtable;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.configuration.ComponentConfiguration;
import org.eclipse.kura.configuration.ConfigurationService;
import org.eclipse.kura.core.testutil.requesthandler.AbstractRequestHandlerTest;
import org.eclipse.kura.core.testutil.requesthandler.RestTransport;
import org.eclipse.kura.core.testutil.requesthandler.Transport.MethodSpec;
import org.eclipse.kura.core.testutil.requesthandler.Transport.Response;
import org.eclipse.kura.util.wire.test.WireTestUtil;
import org.junit.After;
import org.junit.AfterClass;
import org.junit.Before;
import org.junit.BeforeClass;
import org.junit.Test;
import org.osgi.service.cm.Configuration;
import org.osgi.service.cm.ConfigurationAdmin;

public class RestConfigurationTypeValidationTest extends AbstractRequestHandlerTest {

    private static final String H2_DB_SERVICE_PID = "org.eclipse.kura.db.H2DbService";
    private static final String POOL_MAX_SIZE_PROPERTY = "db.connection.pool.max.size";

    private static final String REST_SERVICE_PID = "org.eclipse.kura.internal.rest.configuration.ConfigurationRestService";
    private static final String CONFIGURATION_SERVICE_TARGET = "ConfigurationService.target";
    private static final String REAL_CONFIGURATION_SERVICE_FILTER = "(service.pid=org.eclipse.kura.configuration.ConfigurationService)";
    private static final long REST_SERVICE_REBIND_TIMEOUT_MS = 30000;

    private static Dictionary<String, Object> previousRestServiceProperties;

    private Integer initialPoolMaxSize;
    private Set<Long> snapshotsBeforeUpdate;

    public RestConfigurationTypeValidationTest() {
        super(new RestTransport("configuration/v2"));
    }

    @BeforeClass
    public static void bindRestServiceToRealConfigurationService() throws Exception {
        final Configuration config = getRestServiceConfiguration();
        previousRestServiceProperties = config.getProperties();

        final Dictionary<String, Object> properties = new Hashtable<>();
        properties.put(CONFIGURATION_SERVICE_TARGET, REAL_CONFIGURATION_SERVICE_FILTER);
        config.update(properties);
    }

    @AfterClass
    public static void restoreRestServiceConfiguration() throws Exception {
        final Configuration config = getRestServiceConfiguration();

        if (previousRestServiceProperties == null) {
            config.delete();
        } else {
            config.update(previousRestServiceProperties);
        }
    }

    @Before
    public void waitForRestServiceBoundToRealConfigurationService() throws InterruptedException {
        ((RestTransport) this.transport).setBasicCredentials(Optional.of("admin:admin"));

        final long deadline = System.currentTimeMillis() + REST_SERVICE_REBIND_TIMEOUT_MS;

        while (System.currentTimeMillis() < deadline) {
            final Response response = this.transport.runRequest("/configurableComponents", new MethodSpec("GET"));

            if (response.getStatus() == 200
                    && response.getBody().map(b -> b.contains(H2_DB_SERVICE_PID)).orElse(false)) {
                return;
            }

            Thread.sleep(500);
        }

        fail("the Configuration REST service is not bound to the real ConfigurationService");
    }

    @After
    public void restoreInitialPoolMaxSize() throws Exception {
        if (this.initialPoolMaxSize != null && !this.initialPoolMaxSize.equals(getCurrentPoolMaxSize())) {
            getConfigurationService().updateConfiguration(H2_DB_SERVICE_PID,
                    Collections.singletonMap(POOL_MAX_SIZE_PROPERTY, this.initialPoolMaxSize), false);
        }
    }

    @Test
    public void numericStringForIntegerPropertyIsRejectedOverRest() throws Exception {
        givenCurrentPoolMaxSize();
        givenSnapshotsAreRemembered();

        whenUpdateIsRequestedWith("STRING", "\"20\"");

        thenResponseCodeIs(500);
        thenPoolMaxSizeIs(this.initialPoolMaxSize);
        thenConfigurationAdminHoldsInteger(this.initialPoolMaxSize);
        thenNoSnapshotIsTaken();
    }

    @Test
    public void integerForIntegerPropertyIsAppliedOverRest() throws Exception {
        givenCurrentPoolMaxSize();

        whenUpdateIsRequestedWith("INTEGER", "20");

        thenRequestSucceeds();
        thenPoolMaxSizeIs(20);
        thenConfigurationAdminHoldsInteger(20);
    }

    private void givenCurrentPoolMaxSize() throws Exception {
        final Object value = getCurrentPoolMaxSize();

        assertTrue("expected an Integer value for " + POOL_MAX_SIZE_PROPERTY + " but found " + value,
                value instanceof Integer);
        this.initialPoolMaxSize = (Integer) value;
    }

    private void givenSnapshotsAreRemembered() throws Exception {
        this.snapshotsBeforeUpdate = new TreeSet<>(getConfigurationService().getSnapshots());
    }

    private void whenUpdateIsRequestedWith(final String type, final String jsonValue) {
        whenRequestIsPerformed(new MethodSpec("PUT"), "/configurableComponents/configurations/_update",
                "{\"configs\":[{\"pid\":\"" + H2_DB_SERVICE_PID + "\",\"properties\":{\"" + POOL_MAX_SIZE_PROPERTY
                        + "\":{\"type\":\"" + type + "\",\"value\":" + jsonValue + "}}}]}");
    }

    private void thenPoolMaxSizeIs(final int expected) throws Exception {
        assertEquals(Integer.valueOf(expected), getCurrentPoolMaxSize());
    }

    private void thenConfigurationAdminHoldsInteger(final int expected) throws Exception {
        final ConfigurationAdmin configurationAdmin = WireTestUtil
                .trackService(ConfigurationAdmin.class, Optional.empty()).get(30, TimeUnit.SECONDS);
        final Configuration[] configs = configurationAdmin
                .listConfigurations("(kura.service.pid=" + H2_DB_SERVICE_PID + ")");

        assertNotNull("ConfigurationAdmin has no entry for " + H2_DB_SERVICE_PID, configs);
        assertEquals(1, configs.length);
        assertEquals(Integer.valueOf(expected), configs[0].getProperties().get(POOL_MAX_SIZE_PROPERTY));
    }

    private void thenNoSnapshotIsTaken() throws Exception {
        assertEquals(this.snapshotsBeforeUpdate, new TreeSet<>(getConfigurationService().getSnapshots()));
    }

    private static Object getCurrentPoolMaxSize() throws Exception {
        final ComponentConfiguration config = getConfigurationService().getComponentConfiguration(H2_DB_SERVICE_PID);

        assertNotNull("configuration not found for " + H2_DB_SERVICE_PID, config);
        return config.getConfigurationProperties().get(POOL_MAX_SIZE_PROPERTY);
    }

    private static ConfigurationService getConfigurationService() throws Exception {
        return WireTestUtil
                .trackService(ConfigurationService.class,
                        Optional.of("(service.pid=org.eclipse.kura.configuration.ConfigurationService)"))
                .get(30, TimeUnit.SECONDS);
    }

    private static Configuration getRestServiceConfiguration() throws Exception {
        final ConfigurationAdmin configurationAdmin = WireTestUtil
                .trackService(ConfigurationAdmin.class, Optional.empty()).get(30, TimeUnit.SECONDS);

        return configurationAdmin.getConfiguration(REST_SERVICE_PID, "?");
    }
}
